def transform_v8(grid):
    """For each 1 at (r,c), create pattern spanning cols c, c+1:
    - Rows r-1, r: [8,5], [0,5] at cols c, c+1
    - Row r+1: [0,7] at cols c-1, c (left-aligned version)
    """
    height, width = len(grid), len(grid[0])
    background = 6
    result = [[background for _ in range(width)] for _ in range(height)]

    for r in range(height):
        for c in range(width):
            if grid[r][c] == 1:
                # Pattern top 2 rows: cols c, c+1
                if r - 1 >= 0:
                    result[r-1][c] = 8
                    result[r-1][c+1] = 5
                if r < height:
                    result[r][c] = 0
                    result[r][c+1] = 5

                # Pattern bottom row: cols c-1, c
                if c > 0:
                    result[r+1][c-1] = 0
                if c > 0 and c < width:
                    result[r+1][c] = 7

    return result

